      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, attr_span_kind kind, count(*) n, approx_quantile(duration/1e6, 0.5) p50ms, approx_quantile(duration/1e6, 0.95) p95ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('SELECT ts.route_stations','SELECT ts.route_distances','SELECT ts.route','Transaction.commit') GROUP BY ALL UNION ALL SELECT 'norm', span_name, attr_span_kind, count(*), approx_quantile(duration/1e6, 0.5), approx_quantile(duration/1e6, 0.95) FROM normal_traces WHERE service_name='ts-route-service' AND span_name IN ('SELECT ts.route_stations','SELECT ts.route_distances','SELECT ts.route','Transaction.commit') GROUP BY ALL",
          "claim": "Route-service's own DB client spans (ts.route_stations, ts.route_distances) went from ~0.1 ms p95 normal to 400-650 ms p95 abnormal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, service_name, attr_k8s_pod_name pod, count(*) n, round(avg(value),3) av, round(max(value),3) mx FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-route-service%' OR attr_k8s_pod_name LIKE 'mysql%' GROUP BY ALL UNION ALL SELECT 'norm', metric, service_name, attr_k8s_pod_name, count(*), round(avg(value),3), round(max(value),3) FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'ts-route-service%' OR attr_k8s_pod_name LIKE 'mysql%' GROUP BY ALL ORDER BY metric, p",
          "claim": "Route-service and mysql pod CPU stayed low or fell during the incident, so the slowdown is not CPU saturation."
        }
      ]
    }
